/**
 * @planks("the app is loaded")
 * TodoMVC Application
 */
(function () {
	'use strict';

	var STORAGE_KEY = 'todos';
	var todoList = document.querySelector('.todo-list');
	var newTodoInput = document.querySelector('.new-todo');
	var toggleAllCheckbox = document.querySelector('#toggle-all');
	var clearCompletedButton = document.querySelector('.clear-completed');
	var todoCount = document.querySelector('.todo-count');
	var mainSection = document.querySelector('.main');
	var footer = document.querySelector('.footer');
	var filters = document.querySelector('.filters');

	var todos = [];
	var currentFilter = '/';

	/**
	 * @planks("the user types {string} in the new-todo input and presses Enter")
	 * @planks("a todo {string} exists")
	 * @planks("a completed todo {string} exists")
	 */
	function addTodo(title) {
		title = title.trim();
		if (!title) return;
		todos.push({
			id: Date.now(),
			title: title,
			completed: false
		});
		saveTodos();
		render();
	}

	/**
	 * @planks("the user toggles the checkbox for {string}")
	 * @planks("the user checks the toggle-all checkbox")
	 * @planks("the user unchecks the toggle-all checkbox")
	 */
	function toggleTodo(id) {
		var todo = todos.find(function (t) { return t.id === id; });
		if (todo) {
			todo.completed = !todo.completed;
			saveTodos();
			render();
		}
	}

	/**
	 * @planks("the user clicks the destroy button for {string}")
	 */
	function deleteTodo(id) {
		todos = todos.filter(function (t) { return t.id !== id; });
		saveTodos();
		render();
	}

	/**
	 * @planks("the user types {string} in the edit input and presses Enter")
	 * @planks("the user types {string} in the edit input and blurs")
	 * @planks("the user types {string} in the edit input and presses Escape")
	 * @planks("the user clears the edit input and presses Enter")
	 */
	function editTodo(id, newTitle) {
		var todo = todos.find(function (t) { return t.id === id; });
		if (!todo) return;
		newTitle = newTitle.trim();
		if (!newTitle) {
			deleteTodo(id);
			return;
		}
		todo.title = newTitle;
		saveTodos();
		render();
	}

	/**
	 * @planks("the user clicks the clear-completed button")
	 */
	function clearCompleted() {
		todos = todos.filter(function (t) { return !t.completed; });
		saveTodos();
		render();
	}

	/**
	 * @planks("a todo with title {string} exists in the list")
	 * @planks("no todo with title {string} exists")
	 * @planks("no todos exist")
	 * @planks("the todo {string} is not completed")
	 * @planks("the todo {string} is completed")
	 * @planks("the todo item {string} has the class {string}")
	 * @planks("the todo {string} is visible in the list")
	 * @planks("the todo {string} is not visible in the list")
	 */
	function getVisibleTodos() {
		switch (currentFilter) {
			case '/active':
				return todos.filter(function (t) { return !t.completed; });
			case '/completed':
				return todos.filter(function (t) { return t.completed; });
			default:
				return todos;
		}
	}

	/**
	 * @planks("the todo count shows {string}")
	 */
	function updateCount() {
		var activeCount = todos.filter(function (t) { return !t.completed; }).length;
		var countText = activeCount + ' item' + (activeCount !== 1 ? 's' : '') + ' left';
		todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + countText.split(' ').slice(1).join(' ');
	}

	/**
	 * @planks("the toggle-all checkbox is checked")
	 * @planks("the toggle-all checkbox is not checked")
	 */
	function updateToggleAll() {
		var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
		toggleAllCheckbox.checked = allCompleted;
	}

	/**
	 * @planks("the clear-completed button is hidden")
	 * @planks("the clear-completed button is visible")
	 */
	function updateClearCompleted() {
		var hasCompleted = todos.some(function (t) { return t.completed; });
		clearCompletedButton.style.display = hasCompleted ? '' : 'none';
	}

	/**
	 * @planks("the main section is hidden")
	 * @planks("the main section is visible")
	 * @planks("the footer is hidden")
	 * @planks("the footer is visible")
	 */
	function updateVisibility() {
		var hasTodos = todos.length > 0;
		mainSection.style.display = hasTodos ? '' : 'none';
		footer.style.display = hasTodos ? '' : 'none';
	}

	/**
	 * @planks("the {string} filter is selected")
	 */
	function updateFilters() {
		var links = filters.querySelectorAll('a');
		for (var i = 0; i < links.length; i++) {
			var link = links[i];
			var href = link.getAttribute('href');
			if (href === '#' + currentFilter || href === currentFilter) {
				link.classList.add('selected');
			} else {
				link.classList.remove('selected');
			}
		}
	}

	function render() {
		var visibleTodos = getVisibleTodos();
		todoList.innerHTML = '';

		for (var i = 0; i < visibleTodos.length; i++) {
			var todo = visibleTodos[i];
			var li = document.createElement('li');
			li.dataset.id = todo.id;
			if (todo.completed) {
				li.classList.add('completed');
			}

			var div = document.createElement('div');
			div.className = 'view';

			var checkbox = document.createElement('input');
			checkbox.className = 'toggle';
			checkbox.type = 'checkbox';
			checkbox.checked = todo.completed;
			checkbox.addEventListener('click', (function (id) {
				return function () { toggleTodo(id); };
			})(todo.id));

			var label = document.createElement('label');
			label.textContent = todo.title;
			label.addEventListener('dblclick', (function (li) {
				return function () {
					li.classList.add('editing');
					var editInput = li.querySelector('.edit');
					editInput.focus();
				};
			})(li));

			var destroyButton = document.createElement('button');
			destroyButton.className = 'destroy';
			destroyButton.addEventListener('click', (function (id) {
				return function () { deleteTodo(id); };
			})(todo.id));

			div.appendChild(checkbox);
			div.appendChild(label);
			div.appendChild(destroyButton);

			var editInput = document.createElement('input');
			editInput.className = 'edit';
			editInput.value = todo.title;
			editInput.addEventListener('blur', (function (id, input) {
				return function () {
					var li = input.closest('li');
					if (li && li.classList.contains('editing')) {
						editTodo(id, input.value);
					}
				};
			})(todo.id, editInput));
			editInput.addEventListener('keydown', (function (id, input) {
				return function (e) {
					if (e.key === 'Enter') {
						editTodo(id, input.value);
					} else if (e.key === 'Escape') {
						input.value = todos.find(function (t) { return t.id === id; }).title;
						input.closest('li').classList.remove('editing');
					}
				};
			})(todo.id, editInput));

			li.appendChild(div);
			li.appendChild(editInput);
			todoList.appendChild(li);
		}

		updateCount();
		updateToggleAll();
		updateClearCompleted();
		updateVisibility();
		updateFilters();
	}

	function saveTodos() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function loadTodos() {
		var stored = localStorage.getItem(STORAGE_KEY);
		if (stored) {
			todos = JSON.parse(stored);
		}
	}

	function handleRoute() {
		currentFilter = window.location.hash.replace('#', '') || '/';
		render();
	}

	// Event listeners
	newTodoInput.addEventListener('keydown', function (e) {
		if (e.key === 'Enter') {
			addTodo(newTodoInput.value);
			newTodoInput.value = '';
		}
	});

	toggleAllCheckbox.addEventListener('change', function () {
		var allCompleted = toggleAllCheckbox.checked;
		for (var i = 0; i < todos.length; i++) {
			todos[i].completed = allCompleted;
		}
		saveTodos();
		render();
	});

	clearCompletedButton.addEventListener('click', function () {
		clearCompleted();
	});

	filters.addEventListener('click', function (e) {
		if (e.target.tagName === 'A') {
			e.preventDefault();
			var href = e.target.getAttribute('href');
			window.location.hash = href;
		}
	});

	window.addEventListener('hashchange', handleRoute);

	// Initialize
	loadTodos();
	handleRoute();
	render();
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// Helper: find a todo by title
function findTodo(title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent === title) return item;
  }
  return null;
}

// Helper: get all visible todos
function getVisibleTodos() {
  const items = this.document.querySelectorAll('.todo-list li');
  return Array.from(items).filter(item => item.style.display !== 'none');
}

// ========== Given steps ==========

Given('the app is loaded', function () {
  // App is loaded by Before hook in world.js
  assert(this.document, 'App should be loaded');
});

Given('a todo {string} exists', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

Given('a completed todo {string} exists', function (title) {
  // Create the todo first
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
  // Then mark it as completed
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  const checkbox = todo.querySelector('.toggle');
  checkbox.click();
});

// ========== When steps ==========

When('the user types {string} in the new-todo input and presses Enter', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user toggles the checkbox for {string}', function (title) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  const checkbox = todo.querySelector('.toggle');
  checkbox.click();
});

When('the user double-clicks the label {string}', function (title) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  const label = todo.querySelector('label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('the user types {string} in the edit input and presses Enter', function (title) {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert(editing, 'Should be in editing mode');
  const input = editing.querySelector('.edit');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user types {string} in the edit input and blurs', function (title) {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert(editing, 'Should be in editing mode');
  const input = editing.querySelector('.edit');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user types {string} in the edit input and presses Escape', function (title) {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert(editing, 'Should be in editing mode');
  const input = editing.querySelector('.edit');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert(editing, 'Should be in editing mode');
  const input = editing.querySelector('.edit');
  input.value = '';
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user clicks the destroy button for {string}', function (title) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  const destroy = todo.querySelector('.destroy');
  destroy.click();
});

When('the user clicks the clear-completed button', function () {
  const button = this.document.querySelector('.clear-completed');
  button.click();
});

When('the user checks the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  toggleAll.checked = true;
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the user unchecks the toggle-all checkbox', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  toggleAll.checked = false;
  toggleAll.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('the app is reloaded', function () {
  // Save current todos to localStorage
  const todos = JSON.parse(this.window.localStorage.getItem('todos') || '[]');
  // Reload the app
  this.loadApp();
  // Restore todos to localStorage
  this.window.localStorage.setItem('todos', JSON.stringify(todos));
  // Re-initialize the app with the restored data
  this.window.eval('window.dispatchEvent(new Event("load"))');
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

// ========== Then steps ==========

Then('a todo with title {string} exists in the list', function (title) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist in the list`);
});

Then('no todo with title {string} exists', function (title) {
  const todo = findTodo.call(this, title);
  assert(!todo, `Todo "${title}" should not exist`);
});

Then('no todos exist', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'No todos should exist');
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'New-todo input should be empty');
});

Then('the new-todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(this.document.activeElement, input, 'New-todo input should be focused');
});

Then('the todo {string} is not completed', function (title) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  assert(!todo.classList.contains('completed'), `Todo "${title}" should not be completed`);
});

Then('the todo {string} is completed', function (title) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  assert(todo.classList.contains('completed'), `Todo "${title}" should be completed`);
});

Then('the todo item {string} has the class {string}', function (title, className) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  assert(todo.classList.contains(className), `Todo "${title}" should have class "${className}"`);
});

Then('the edit input for {string} contains {string}', function (title, value) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  const input = todo.querySelector('.edit');
  assert.strictEqual(input.value, value, `Edit input should contain "${value}"`);
});

Then('the edit input for {string} is focused', function (title) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  const input = todo.querySelector('.edit');
  assert.strictEqual(this.document.activeElement, input, 'Edit input should be focused');
});

Then('the clear-completed button is hidden', function () {
  const button = this.document.querySelector('.clear-completed');
  const style = this.window.getComputedStyle(button);
  assert(style.display === 'none' || button.offsetParent === null, 'Clear-completed button should be hidden');
});

Then('the clear-completed button is visible', function () {
  const button = this.document.querySelector('.clear-completed');
  const style = this.window.getComputedStyle(button);
  assert(style.display !== 'none' && button.offsetParent !== null, 'Clear-completed button should be visible');
});

Then('the todo count shows {string}', function (countText) {
  const count = this.document.querySelector('.todo-count');
  assert(count.textContent.includes(countText), `Todo count should show "${countText}"`);
});

Then('the todo {string} is visible in the list', function (title) {
  const todo = findTodo.call(this, title);
  assert(todo, `Todo "${title}" should exist`);
  const style = this.window.getComputedStyle(todo);
  assert(style.display !== 'none', `Todo "${title}" should be visible`);
});

Then('the todo {string} is not visible in the list', function (title) {
  const todo = findTodo.call(this, title);
  if (todo) {
    const style = this.window.getComputedStyle(todo);
    assert(style.display === 'none', `Todo "${title}" should not be visible`);
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert(toggleAll.checked, 'Toggle-all checkbox should be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert(!toggleAll.checked, 'Toggle-all checkbox should not be checked');
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  assert(style.display === 'none', 'Main section should be hidden');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  assert(style.display !== 'none', 'Main section should be visible');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  assert(style.display === 'none', 'Footer should be hidden');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  assert(style.display !== 'none', 'Footer should be visible');
});

Then('the {string} filter is selected', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  let found = false;
  for (const link of links) {
    if (link.textContent === filterName && link.classList.contains('selected')) {
      found = true;
      break;
    }
  }
  assert(found, `Filter "${filterName}" should be selected`);
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

